\begin{align*} \det(A) &= \sec^2 x \begin{vmatrix} \cos^2 x & \csc^2 x \\ \cos^2 x & \cot^2 x \end{vmatrix} - 1 \begin{vmatrix} \cos^2 x & \csc^2 x \\ 1 & \cot^2 x \end{vmatrix} + 1 \begin{vmatrix} \cos^2 x & \cos^2 x \\ 1 & \cos^2 x \end{vmatrix} \\ &= \sec^2 x (\cos^2 x \cot^2 x - \csc^2 x \cos^2 x) - (\cos^2 x \cot^2 x - \csc^2 x) + (\cos^4 x - \cos^2 x) \\ &= \sec^2 x \cos^2 x (\cot^2 x - \csc^2 x) - \cos^2 x \cot^2 x + \csc^2 x + \cos^4 x - \cos^2 x \\ &= \frac{1}{\cos^2 x} \cos^2 x (\frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x}) - \frac{\cos^2 x \cos^2 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \left(\cot^2 x - \csc^2 x\right) - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \cot^2 x - \csc^2 x - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x}{\sin^2 x} - \frac{1}{\sin^2 x} - \frac{\cos^4 x}{\sin^2 x} + \frac{1}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x - \cos^4 x}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x (1 - \cos^2 x)}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \frac{\cos^2 x \sin^2 x}{\sin^2 x} + \cos^4 x - \cos^2 x \\ &= \cos^2 x + \cos^4 x - \cos^2 x \\ &= \cos^4 x \end{align*} 
The determinant is $\cos^4 x$. 

\boxed{\cos^4 x}

