\text{The area of an equilateral triangle with side length } s \text{ is } \frac{\sqrt{3}}{4} s^2 \text{, so we have } \\
\text{Area}_{\text{small}} = \frac{\sqrt{3}}{4} s_{\text{small}}^2 \text{ and } \text{Area}_{\text{large}} = \frac{\sqrt{3}}{4} s_{\text{large}}^2 \\
\text{We are given that } \text{Area}_{\text{large}} = 16 \times \text{Area}_{\text{small}} \implies \frac{\sqrt{3}}{4} s_{\text{large}}^2 = 16 \left( \frac{\sqrt{3}}{4} s_{\text{small}}^2 \right) \\
\implies s_{\text{large}}^2 = 16 s_{\text{small}}^2 \implies s_{\text{large}} = 4 s_{\text{small}} \text{ (since } s_{\text{large}} > 0 \text{ and } s_{\text{small}} > 0)} \\
\text{Substituting } s_{\text{small}} = 15 - s_{\text{large}} \text{ into } s_{\text{large}} = 4 s_{\text{small}} \text{, we have } \\
s_{\text{large}} = 4(15 - s_{\text{large}}) \implies s_{\text{large}} = 60 - 4 s_{\text{large}} \implies 5 s_{\text{large}} = 60 \implies s_{\text{large}} = 12 \\
s_{\text{small}} = 15 - s_{\text{large}} = 15 - 12 = 3 \\
\text{The area of the larger triangle is } \text{Area}_{\text{large}} = \frac{\sqrt{3}}{4} s_{\text{large}}^2 = \frac{\sqrt{3}}{4} (12)^2 = \frac{\sqrt{3}}{4} (144) = 36 \sqrt{3} \text{ square inches}
